def region(start):
    q=collections.deque([start]); seen={start}
    while q:
        r,c=q.popleft()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc]!='#' and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen
s=region((1,1)); e=region((27,27))
