grid=[list(line) for line in open('maze.txt').read().splitlines()]
R=len(grid); C=len(grid[0])
start=next((i,j) for i,row in enumerate(grid) for j,ch in enumerate(row) if ch=='@')
end=next((i,j) for i,row in enumerate(grid) for j,ch in enumerate(row) if ch=='E')
from collections import deque
q=deque([start]); prev={start:None}
dirs={'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
while q:
    cur=q.popleft()
    if cur==end: break
    for d,(dr,dc) in dirs.items():
        nr,nc=cur[0]+dr,cur[1]+dc
        if 0<=nr<R and 0<=nc<C and grid[nr][nc]!='#' and (nr,nc) not in prev:
            prev[(nr,nc)]=(cur,d)
            q.append((nr,nc))
path=[]
cur=end
while cur!=start:
    p,d=prev[cur]
    path.append(d)
    cur=p
path.reverse()
print(len(path))
print(' '.join(path))
""}

